import assert from 'assert';
import {randomBytes} from 'crypto';
globalThis.crypto={randomUUID:()=>randomBytes(16).toString('hex')};
import {example,parseDraft} from './model.js';
import {createTemplate} from './templates.js';
import fs from 'fs';
const context={relation:{oid:1,schema:'template_checks',name:'orders',kind:'r',can_select_all:true},details:{oid:1,foreign_keys:[],columns:[{number:1,name:'id',data_type:'integer',type_oid:23,can_update:false},{number:2,name:'amount',data_type:'integer',type_oid:23,can_update:true},{number:3,name:'status',data_type:'text',type_oid:25,can_update:true}]},joined:null};
const base={schema:'template_checks',table:'orders',mode:'value',column:{side:'source',name:'status'},filter:{side:'source',name:'id',parameter:'input_value'},join:null};
const project=example();project.name='template_lookup';project.model.name='Подписи сохраняются';
let counter=0;const id=()=>`template_${++counter}`;
const lookup=createTemplate(project,base,context,'lookup',id);assert.equal(lookup.project.returnType,'text');assert.equal(lookup.project.parameters.length,1);assert.deepEqual(parseDraft(JSON.stringify(lookup.project)),lookup.project);assert.equal(lookup.project.model.name,project.model.name);
assert.equal(lookup.project.blocks[0].assistant.table,'orders');assert(!lookup.sql.includes('UPDATE'));
console.log('PASS templates: lookup uses typed metadata and preserves model/settings');
const sum=createTemplate({...project,name:'template_sum'},{...base,column:{side:'source',name:'amount'},filter:null},context,'sum',id);assert.equal(sum.project.parameters.length,0);assert(sum.sql.includes('pg_catalog.sum('));
assert.throws(()=>createTemplate(project,base,context,'sum',id));
console.log('PASS templates: integer sum and unsupported type rejection');
const status=createTemplate({...project,name:'template_status'},base,context,'status',id);assert.equal(status.project.kind,'procedure');assert.equal(status.project.parameters[1].type,'text');assert(status.sql.includes('SET "status" = $2'));assert(status.sql.includes('ROW_COUNT'));assert(status.sql.includes("'P0002'"));assert(status.sql.includes("'21000'"));
assert.throws(()=>createTemplate(project,base,{...context,details:{...context.details,columns:context.details.columns.map(c=>({...c,can_update:false}))}},'status',id));
console.log('PASS templates: status is parameterized, checks affected rows and UPDATE privileges');
assert.throws(()=>createTemplate(project,{...base,filter:null},context,'lookup',id));assert.throws(()=>createTemplate(project,{...base,table:'missing'},context,'lookup',id));assert.equal(project.kind,'function');assert.equal(project.variables[0].name,'running_total');
console.log('PASS templates: malformed selection rejected without mutating original project');
const fixtures=[lookup.project,sum.project,status.project];
const path=new URL('../server/tests/template_projects.json',import.meta.url),encoded=JSON.stringify(fixtures,null,2)+'\n';
if(process.argv.includes('--write-fixtures'))fs.writeFileSync(path,encoded);else assert.equal(fs.readFileSync(path,'utf8'),encoded);
console.log('PASS templates: actual generated projects shared with PostgreSQL tests');
